package vn.edu.hcmute.example3; import java.math.BigDecimal; import org.springframework.security.core.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class ProductController {private final ProductService service; ProductController(ProductService s){service=s;} private boolean admin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));} @GetMapping({"/","/products"}) String list(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,Authentication a,Model m){m.addAttribute("result",service.page(a.getName(),q,page,admin(a)));m.addAttribute("q",q);return "products";} @GetMapping("/products/new") String create(Model m){m.addAttribute("product",null);return "product-form";} @GetMapping("/products/{id}/edit") String edit(@PathVariable Long id,Authentication a,Model m){m.addAttribute("product",service.one(id,a.getName(),admin(a)));return "product-form";} @PostMapping("/products/save") String save(@RequestParam(required=false)Long id,@RequestParam String name,@RequestParam(defaultValue="")String description,@RequestParam BigDecimal price,@RequestParam(defaultValue="")String imageUrl,Authentication a,RedirectAttributes ra){service.save(id,a.getName(),admin(a),name,description,price,imageUrl);ra.addFlashAttribute("message","Đã lưu sản phẩm.");return "redirect:/products";} @PostMapping("/products/{id}/delete") String delete(@PathVariable Long id,Authentication a,RedirectAttributes ra){service.delete(id,a.getName(),admin(a));ra.addFlashAttribute("message","Đã xóa sản phẩm.");return "redirect:/products";}}
